package marketplace

// Pilot batch: the 60 pilot buyer samples and the 40-message held-out set,
// read the way production reads a first message (FirstReading ->
// ParseSelectionReply -> heuristic extraction -> workflow.Assess). The
// extraction is generated by scripts/eval/build_pilot_corpus.py.

import (
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"testing"

	"github.com/middleman/backend/internal/workflow"
)

type pilotCase struct {
	ID         int            `json:"id"`
	Set        string         `json:"set"`
	Kind       string         `json:"kind"`
	Category   string         `json:"category"`
	Text       string         `json:"text"`
	Extraction map[string]any `json:"extraction"`
}

func TestPilotSamplesThroughThePolicy(t *testing.T) {
	b, err := os.ReadFile("testdata/pilot_corpus.json")
	if err != nil {
		t.Fatalf("pilot corpus: %v (run scripts/eval/build_pilot_corpus.py)", err)
	}
	var doc struct {
		Cases []pilotCase `json:"cases"`
	}
	if err := json.Unmarshal(b, &doc); err != nil {
		t.Fatal(err)
	}
	// Non-requests and vague messages that still open a request (Majo then
	// asks what the buyer wants). 10 when this test was written; never raise it.
	const maxOpened = 10
	opened := 0
	dist := map[string]int{}
	for _, pc := range doc.Cases {
		got, field := readFirstMessage(t, corpusCase{ID: fmt.Sprint(pc.ID), Text: pc.Text, Extraction: pc.Extraction})
		key := pc.Set + "/" + pc.Kind + " -> " + got
		if field != "" {
			key += "/" + field
		}
		dist[key]++
		t.Logf("%s #%d %-12s -> %s/%s  %q", pc.Set, pc.ID, pc.Kind, got, field, pc.Text)
		switch pc.Kind {
		case "request":
			// A real request is never dropped as small talk, never held as a
			// restricted item, and never mistaken for an offer selection.
			if got == "small_talk" || got == workflow.OutcomePolicy || got == "selection_reply" {
				t.Errorf("#%d %q: a buyer request was read as %s", pc.ID, pc.Text, got)
			}
		case "non_request", "vague":
			// Small talk and vague messages are never confirmed and routed.
			if got == workflow.OutcomeClear {
				t.Errorf("#%d %q: would be confirmed and sent to vendors", pc.ID, pc.Text)
			}
			if got != "small_talk" && got != "selection_reply" && got != "reference_without_context" {
				opened++
			}
		}
	}
	if opened > maxOpened {
		t.Errorf("%d non-requests/vague messages opened a request (max %d)", opened, maxOpened)
	}
	keys := make([]string, 0, len(dist))
	for k := range dist {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		t.Logf("%3d  %s", dist[k], k)
	}
}
